34: @Mod(SimpleRail.MOD_ID)
35: public class SimpleRail {
36: 
37:   private static final Logger LOGGER = LogManager.getLogger();
38: 
39:   public static final String MOD_ID = "simplerail";
40:   public static final String MOD_NAME = "Simple Rail";
41: 
42:   public SimpleRail() {
43:     FMLJavaModLoadingContext.get().getModEventBus().addListener(this::setup);
44:     FMLJavaModLoadingContext.get().getModEventBus().addListener(this::enqueueIMC);
45:     FMLJavaModLoadingContext.get().getModEventBus().addListener(this::processIMC);
46:     FMLJavaModLoadingContext.get().getModEventBus().addListener(this::doClientStuff);
47: 
48:     ModLoadingContext.get().registerConfig(Type.COMMON, CommonConfig.SPEC);
49: 
50:     MinecraftForge.EVENT_BUS.register(this);
51: 
52:     SimpleRailDataSerializers.setup();
53:     SimpleRailProperties.setup();
54:     SimpleRailTags.setup();
55:     Registration.setup();
56:   }
57: 
58:   private void setup(final FMLCommonSetupEvent event) {
59:     LOGGER.info("HELLO FROM PREINIT");
60:     LOGGER.info("DIRT BLOCK >> {}", Blocks.DIRT.getRegistryName());
61:   }
62: 
63:   private void doClientStuff(final FMLClientSetupEvent event) {
64:     LOGGER.info("Got game settings");
65: 
66:     Render.setup();
67:   }
68: 
69:   private void enqueueIMC(final InterModEnqueueEvent event) {
70:     InterModComms.sendTo("simplerail", "helloworld", () -> {
71:       LOGGER.info("Hello world from the MDK");
72:       return "Hello world";
73:     });
74:   }
75: 
76:   private void processIMC(final InterModProcessEvent event) {
77:     LOGGER.info("Got IMC {}", event.getIMCStream().map(m -> m.getMessageSupplier().get()).collect(Collectors.toList()));
78:   }
79: 
80:   @SubscribeEvent
81:   public void onServerStarting(FMLServerStartingEvent event) {
82:     // do something when the server starts
83:     LOGGER.info("HELLO from server starting");
84:   }
85: 
86:   @Mod.EventBusSubscriber(bus = Mod.EventBusSubscriber.Bus.MOD)
87:   public static class RegistryEvents {
88:     @SubscribeEvent
89:     public static void onBlocksRegistry(final RegistryEvent.Register<Block> blockRegistryEvent) {
90:       LOGGER.info("HELLO from Register Block");
91:     }
92: 
93:     @SubscribeEvent
94:     public static void registerTE(RegistryEvent.Register<TileEntityType<?>> evt) {
95:       TileEntities.register(evt);
96:     }
97:   }
98: 
99:   @SubscribeEvent
100:   public void entityEnteredChunk(EnteringChunk event) {
101:     ChunkEventManager.run(event);
102:   }
